import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

/** The committed contract (ADR-0008 draft, CLAUDE.md rule 6): services/algo-api/openapi.json. */
export const SNAPSHOT_PATH = fileURLToPath(new URL("../../../services/algo-api/openapi.json", import.meta.url));
export const GENERATED_PATH = fileURLToPath(new URL("./schema.gen.ts", import.meta.url));

const BANNER = [
  "// GENERATED by `just openapi` (packages/api-client/src/generate.ts) from services/algo-api/openapi.json.",
  "// Do not edit by hand: change the API, run `just openapi`, commit both files.",
  "",
].join("\n");

export async function renderSchemaTypes(snapshotPath: string = SNAPSHOT_PATH): Promise<string> {
  const spec = JSON.parse(readFileSync(snapshotPath, "utf8")) as Parameters<typeof openapiTS>[0];
  const ast = await openapiTS(spec, { alphabetize: true, exportType: true, defaultNonNullable: false });
  return BANNER + astToString(ast);
}
